import * as React from 'react';
import { render, fireEvent, wait } from 'react-testing-library';
import * as Yup from 'yup';

import {
  Formik,
  prepareDataForValidation,
  FormikProps,
  FormikConfig,
} from '../src';
import { noop } from './testHelpers';

jest.spyOn(global.console, 'warn');

interface Values {
  name: string;
  age?: number;
}

function Form({
  values,
  touched,
  handleSubmit,
  handleChange,
  handleBlur,
  status,
  errors,
  isSubmitting,
}: FormikProps<Values>) {
  return (
    <form onSubmit={handleSubmit} data-testid="form">
      <input
        type="text"
        onChange={handleChange}
        onBlur={handleBlur}
        value={values.name}
        name="name"
        data-testid="name-input"
      />
      {touched.name && errors.name && <div id="feedback">{errors.name}</div>}
      {isSubmitting && <div id="submitting">Submitting</div>}
      {status && !!status.myStatusMessage && (
        <div id="statusMessage">{status.myStatusMessage}</div>
      )}
      <button type="submit" data-testid="submit-button">
        Submit
      </button>
    </form>
  );
}

const InitialValues = {
  name: 'jared',
  age: 30,
};

function renderFormik<V = Values>(props?: Partial<FormikConfig<V>>) {
  let injected: FormikProps<V>;
  const { rerender, ...rest } = render(
    <Formik
      onSubmit={noop as any}
      initialValues={InitialValues as any}
      {...props}
    >
      {formikProps =>
        (injected = formikProps) && (
          <Form {...((formikProps as unknown) as FormikProps<Values>)} />
        )
      }
    </Formik>
  );
  return {
    getProps(): FormikProps<V> {
      return injected;
    },
    ...rest,
    rerender: () =>
      rerender(
        <Formik
          onSubmit={noop as any}
          initialValues={InitialValues as any}
          {...props}
        >
          {formikProps =>
            (injected = formikProps) && (
              <Form {...((formikProps as unknown) as FormikProps<Values>)} />
            )
          }
        </Formik>
      ),
  };
}

describe('<Formik>', () => {
